from pathlib import Path
import os
home = Path.home()
roots = [home]
# Include /home/* user profiles if readable, since “user profile” may not be root in containerized setups.
home_dir = Path('/home')
if home_dir.exists():
    roots += [p for p in home_dir.iterdir() if p.is_dir()]

exts = {'.pst', '.ost', '.mbox'}
mbox_names = {'mbox', 'inbox', 'sent', 'archive', 'archives'}
found = []
skipped = []

def looks_like_mbox(path):
    # Lightweight signature check for extensionless mbox-like files.
    try:
        if not path.is_file() or path.stat().st_size == 0:
            return False
        with path.open('rb') as f:
            chunk = f.read(4096)
        return chunk.startswith(b'From ') or b'\nFrom ' in chunk[:4096]
    except Exception:
        return False

for root in roots:
    for dirpath, dirnames, filenames in os.walk(root, topdown=True, onerror=lambda e: skipped.append((getattr(e, 'filename', '?'), str(e)))):
        # Avoid pseudo/cache-heavy dirs that are unlikely to hold mail archives.
        dirnames[:] = [d for d in dirnames if d not in {'.cache', 'node_modules', '.npm', '.cargo', '.rustup', '.local/share/Trash'}]
        dp = Path(dirpath)
        for fn in filenames:
            p = dp / fn
            low = fn.lower()
            reason = None
            if Path(low).suffix in exts:
                reason = Path(low).suffix.upper().lstrip('.')
            elif low in mbox_names and looks_like_mbox(p):
                reason = 'MBOX signature'
            if reason:
                try:
                    st = p.stat()
                    size = st.st_size
                except Exception:
                    size = -1
                found.append((str(p), reason, size))

print(f'SEARCH_ROOTS={", ".join(map(str, roots))}')
print(f'FOUND_COUNT={len(found)}')
for path, reason, size in sorted(found):
    size_s = 'unknown' if size < 0 else str(size)
    print(f'{reason}\t{size_s}\t{path}')
if skipped:
    print(f'SKIPPED_COUNT={len(skipped)}')
    for path, err in skipped[:20]:
        print(f'SKIPPED\t{path}\t{err}')
