from pathlib import Path
import os
home = Path.home()
roots = [home]
home_dir = Path('/home')
if home_dir.exists():
    roots += [p for p in home_dir.iterdir() if p.is_dir()]

exts = {'.pst', '.ost', '.mbox'}
mbox_names = {'mbox', 'inbox', 'sent', 'archive', 'archives'}
found = []

def looks_like_mbox(path):
    try:
        if not path.is_file() or path.stat().st_size == 0:
            return False
        with path.open('rb') as f:
            chunk = f.read(4096)
        return chunk.startswith(b'From ') or b'\nFrom ' in chunk
    except Exception:
        return False

def human(n):
    units=['B','KiB','MiB','GiB','TiB']
    x=float(n)
    for u in units:
        if x < 1024 or u == units[-1]:
            return f'{x:.1f} {u}' if u != 'B' else f'{int(x)} B'
        x /= 1024

for root in roots:
    for dirpath, dirnames, filenames in os.walk(root, topdown=True, onerror=lambda e: None):
        dirnames[:] = [d for d in dirnames if d not in {'.cache', 'node_modules', '.npm', '.cargo', '.rustup', '.local/share/Trash'}]
        dp = Path(dirpath)
        for fn in filenames:
            p = dp / fn
            low = fn.lower()
            if Path(low).suffix in exts or (low in mbox_names and looks_like_mbox(p)):
                try:
                    found.append((str(p), p.stat().st_size))
                except Exception:
                    pass

total = sum(s for _, s in found)
print(f'SEARCH_ROOTS={", ".join(map(str, roots))}')
print(f'FILE_COUNT={len(found)}')
print(f'TOTAL_BYTES={total}')
print(f'TOTAL_HUMAN={human(total)}')
for path, size in sorted(found):
    print(f'{size}\t{human(size)}\t{path}')
